// Rebuild of the supplied landing/authentication exports. Only photograph
// regions are reused from PNGs; text, navigation, cards and buttons are HTML.
const crops={group:['home',178,2398,500,268],employers:['home',711,2398,497,268],skills:['home',169,1548,318,177],connections:['home',520,1548,319,177],tomorrow:['home',869,1548,318,177],supervisor:['company',97,997,509,287],company:['company',791,997,510,287],career:['company',467,1529,509,286],portrait:['company',246,2427,279,267]};
export function photo(name,cls='',label='MenteeLog students'){const [file,x,y,w,h]=crops[name]||crops.group;return `<svg class="reference-photo ${cls}" viewBox="${x} ${y} ${w} ${h}" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${label}"><image href="./assets/references/${file}.png" width="${file==='home'?1359:1400}" height="${file==='home'?4633:5211}"/></svg>`;}
const partners=['Accenture PH','Globe Telecom','BDO Unibank','Meralco','SM Technologies','PLDT','Metrobank','PhilStar Digital'];
function partnerSection(dark=false){return `<section class="partner-section ${dark?'maroon':''}"><h3>ACCREDITED HOST TRAINING ESTABLISHMENTS</h3><div class="partner-list">${partners.map(p=>`<span>${p}</span>`).join('')}</div></section>`;}
function joinSection(safe=true){return `<section class="join-section">${safe?'<p class="public-kicker">— Safe. Verified. Reliable. —</p><h2>Strong Local Partnerships, Nationwide.</h2><p class="public-small">Trusted companies. Real opportunities.</p>':''}<p class="public-kicker">— Join MenteeLog —</p><h2>Where Talent Connects with Opportunity.</h2><p class="public-small">Empowering careers and simplifying hiring: Menteelog makes connecting with skilled Filipino interns effortless.</p><a class="btn" href="#/login">Get Started</a></section>`;}
function footer(){return `<footer class="reference-footer"><div class="footer-contact"><a href="#/" aria-label="MenteeLog home"><img class="footer-logo" src="./assets/logo.svg" alt="MenteeLog"></a><p>✉ &nbsp;info@menteelog.com</p><p>⌖ &nbsp;Iloilo, Philippines</p></div><h2>Inspiring Excellence.<br><span>Linking Opportunities.</span><br>Transforming the Future.</h2><div class="footer-legal"><p>© Copyright 2025 OJT Connect. All Rights Reserved.</p><button class="footer-policy" data-action="privacy">Privacy and Cookies Policy</button><div class="social-symbols" aria-label="Social media icons from the design"><span>▣</span><span>f</span><span>◎</span><span>♪</span><span>▶</span></div></div></footer>`;}
const homeJobs=[['A','Technology Analyst Intern','Accenture Philippines','BSCS / BSIT','BGC, Taguig',12],['G','Network Engineering Intern','Globe Telecom','BSEE / BSIT','Pioneer, Mandaluyong',8],['B','FinTech & Systems Intern','BDO Unibank','BSCS / BSBA','Makati CBD',6],['M','ICT Infrastructure Intern','Meralco','BSECE / BSIT','Ortigas, Pasig',4],['P','Software Development Intern','PhilStar Digital','BSCS / BSIT','Makati',5],['S','Business Intelligence Intern','SM Technologies','BSCS / BSBA','Mall of Asia, Pasay',10]];
export function publicLanding(page,{brand,icon}){const selected=['students','supervisor','career-centers','company'].includes(page)?page:'home';const nav=[['home','Home'],['students','Students'],['supervisor','Supervisor'],['career-centers','Career Centers'],['company','Company']];const heroes={home:['One Platform.<br>Every OJT Journey.','Seamlessly connect students, industry supervisors, and OJT<br>coordinators. From placement to completion — fully digital, fully<br>tracked.','Get Started — It’s Free','group','Student'],students:['BE NOTICED. GET PLACED.','Connect with accredited local and international internship opportunities.','Begin Your OJT Journey','connections','Student'],supervisor:['PARTNER SMARTER.<br>MANAGE INTERNS EFFORTLESSLY.','Connect with verified student interns,<br>streamline MOA accreditations, and evaluate performance in one place.','Become a Partner HTE','supervisor','Supervisor'],'career-centers':["STREAMLINE OJT GOVERNANCE & COMPLIANCE",'Manage student placements, track real-time hours, and monitor MOA accreditations in one platform.','Access Coordinator Portal','career','Coordinator'],company:['MENTEELOG','Manage student placements, track real-time hours, and monitor MOA accreditations in one platform','Get Started','company','Student']};const [title,subtitle,cta,img,role]=heroes[selected];return `<div class="public-site public-${selected}"><header class="reference-header">${brand()}<nav aria-label="Public navigation">${nav.map(([id,label])=>`<a href="#/${id==='home'?'':'public/'+id}" class="${selected===id?'selected':''}" ${selected===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="btn" href="#/login">Sign In</a></header><main id="main" tabindex="-1"><section class="reference-hero">${photo(img,'hero-photo')}<div class="hero-overlay"></div><div class="reference-hero-content"><span class="hero-pill">${icon('shield')} Real-time OJT Placement & Tracking</span><h1>${title}</h1><p>${subtitle}</p><div class="hero-cta"><a class="btn" data-role="${role}" href="#/login">${cta}</a>${selected==='home'?'<button class="btn watch-button" data-action="watch-demo">Watch Demo</button>':''}</div></div></section>${selected==='home'?homeBody(icon):selected==='company'?companyBody():roleBody(selected,icon)}${selected==='home'?partnerSection()+joinSection():selected==='company'?joinSection(false):partnerSection(selected!=='students')+joinSection()}</main>${footer()}</div>`;}
function homeBody(icon){return `<section class="opportunities reference-width"><div class="row between"><div><h2>Open OJT Opportunities</h2><p>Currently accepting applications for AY 2025–2026</p></div><div class="public-filters"><select id="public-course" aria-label="Filter opportunities by course"><option value="All">All Courses</option><option>BSCS</option><option>BSIT</option><option>BSBA</option><option>BSEE</option><option>BSECE</option></select><select id="public-location" aria-label="Filter opportunities by location"><option value="All">All Locations</option>${['Taguig','Mandaluyong','Makati','Pasig','Pasay'].map(v=>`<option>${v}</option>`).join('')}</select></div></div><div class="home-jobs">${homeJobs.map(([initial,title,company,courses,location,slots])=>`<article class="home-job" data-courses="${courses}" data-location="${location}"><div class="row"><span class="home-job-logo">${initial}</span><div><h3>${title}</h3><p>${company}</p></div></div><ul><li>${icon('users')} ${courses}</li><li>${icon('pin')} ${location}</li><li>${icon('users')} ${slots} slots available</li></ul><a class="btn" href="#/login">Apply Now</a></article>`).join('')}</div><p id="public-empty" class="small" hidden>No opportunities match these filters.</p></section><section class="why-section reference-width"><p class="section-kicker">— Why MenteeLog is the Right Choice —</p><h2>Aligning skills with opportunities:<br>connecting driven interns and trusted employers.</h2><p class="public-small">Simplifying local internships through trusted listings and authentic paths to employment.</p><div class="public-stats">${[['1,240+','Registered Students'],['86','Accredited HTEs'],['98%','Placement Rate'],['500K+','DTR Hours Logged']].map(([n,l])=>`<div><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><div class="benefit-grid">${[['skills','Unlocking Capabilities','— Grow Your Skills —','Build confidence, gain experience, and step directly into your field. Menteelog gives you guided app features and verified internships to fast-track your career growth.'],['connections','Connecting Opportunities','— Step Into Your Career —','Discover relevant roles, apply fast, and step directly into your field. Menteelog aligns your skills with real-world opportunities across the Philippines and beyond.'],['tomorrow','Building a Stronger Tomorrow','— Define Your Career Path —','Build your future on a solid foundation. Menteelog brings interns and companies together through trusted opportunities designed for real career advancement.']].map(([p,t,k,d])=>`<article class="benefit-card">${photo(p)}<div><h3>${t}</h3><p class="card-kicker">${k}</p><p>${d}</p><a class="btn" href="#/public/students">Learn more</a></div></article>`).join('')}</div></section><section class="how-section"><p class="section-kicker">— How MenteeLog Works —</p><h2>Simplifying Internship Hiring for Students and Verified Companies</h2><p class="public-small">Post opportunities, submit applications, and connect directly—Menteelog streamlines your entire internship workflow.</p><div class="how-grid reference-width">${[['group','For Interns','— Your Path to the Right Internship —','Find opportunities that truly fit your goals.',['Explore verified job listings from global companies','Search by role, skills, location, setup, and date posted','Apply to multiple listings with ease','Track your applications inside the platform','Get interview invites directly from employers','Build early exposure to real industry environments'],'students'],['employers','For Employers','— A Simpler Way to Find Talent —','Connect with skilled and dependable Filipino interns.',['Post clear and detailed OJT listings','Access a diverse pool of student applicants','Message and manage candidates on the platform','Schedule interviews in-app','Streamline your entire OJT recruitment workflow','Gain visibility across hundreds of active student users'],'supervisor']].map(([p,t,k,d,items,to])=>`<article class="how-card">${photo(p)}<div><h3>${t}</h3><p class="card-kicker">${k}</p><p>${d}</p><ul>${items.map(i=>`<li>${i}</li>`).join('')}</ul><a class="btn" href="#/public/${to}">Learn more</a></div></article>`).join('')}</div></section>`;}
function roleBody(page,icon){let title,kicker,sub,items;if(page==='students'){title='YOUR SEAMLESS PATH TO PLACEMENT';kicker='— How MenteeLog Works —';sub='Discover accredited opportunities, log your hours, track performance, and fulfill your OJT requirements—all in one platform.';items=[['pin','Discover','accredited listings from partner HTEs'],['search','Apply','with one-click resume attachments'],['file','Track','to multiple listings with ease'],['chart','Filter','by program, required skills, and location'],['users','Log','GPS-verified clock-ins and daily task summaries'],['briefcase','Complete','supervisor approvals and live hour count']];}else if(page==='supervisor'){title='A STREAMLINED PATHWAY FOR INDUSTRY PARTNERS';kicker='— Host Training Establishment (HTE) Ecosystem —';sub='Onboard student interns, satisfy institutional compliance, and review performance seamlessly.';items=[['plus','Post Placements','Publish OJT roles tied to degree tracks'],['users','Review Applicants','Screen verified student profiles and resumes'],['briefcase','Track Candidates','Manage application pipelines and offers'],['users','Verify DTR','Approve GPS clock-ins and daily task logs workflow'],['chart','Manage MOAs','Track company accreditations and renewals'],['star','Evaluate Interns','Submit final supervisor performance reviews']];}else{title="ELEVATE YOUR INSTITUTION’S OJT MANAGEMENT";kicker='';sub='';items=[['users','Manage HTEs','Accredit partner companies and track active listings'],['briefcase','Place Students','Match interns with accredited host companies'],['target','Resolve Incidents','Handle student reports, mediation, and reassignments'],['chart','Monitor Hours','Audit GPS-verified DTR logs and progress live'],['file','Govern MOAs','Track document renewals and legal compliance'],['star','Generate Reports','Export batch certificates and partner analytics']];}return `<section class="role-info ${page==='students'?'maroon':''}"><p class="section-kicker">${kicker}</p><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}<div class="role-feature-grid reference-width">${items.map(([i,t,d])=>`<article><span class="feature-icon">${icon(i)}</span><div><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div>${page==='students'?`<div class="industry-list reference-width"><p class="section-kicker">— Explore By Industry & Specialization —</p><h2>Find Internships Across Popular Fields</h2><p>Browse accredited host training establishments by domain, academic track, or career interest.</p><div>${['Design & UI/UX','Marketing','Others','Computer and Technology','Retail','Finance','Advertising and Marketing','Design','Development','Multimedia','Software Engineering','Supply Chain','Administration','Data Science / Analytics','Human Resources','Project Management','Information Technology','Customer Services','Sales','Business','Research'].map(t=>`<a href="#/login">${t}</a>`).join('')}</div></div>`:''}</section>`;}
function companyBody(){return `<section class="company-about reference-width"><p class="section-kicker">— About MenteeLog —</p><h2>Bridging Academic Standards and<br>Real-World Industry Exposure</h2><p class="company-intro">Designed as a single-institution On-the-Job Training management platform, Menteelog simplifies OJT workflows for students, host training establishments, and academic coordinators. By replacing fragmented manual records with automated GPS time logging, digital document handling, and structured MOA tracking, Menteelog ensures seamless compliance and transparent career growth.</p><div class="company-values">${[['supervisor','Empowering Interns','— Verified Growth —','Equipping students with GPS-verified daily time records, verified placement directories, and real-time task tracking to build workforce readiness.'],['company','Streamlining Governance','— Institutional Compliance —','Centralizing MOA accreditations, disciplinary workflows, and mediation channels exclusively for academic coordinators and department heads.'],['career','Building Partnerships','— Industry Integration —','Connecting host training establishments with student talent, automating supervisor attendance approvals, and generating batch performance reports.']].map(([p,t,k,d])=>`<article>${photo(p)}<h3>${t}</h3><p>${k}</p><p>${d}</p></article>`).join('')}</div></section><section class="team-section maroon"><h2>THE TEAM BEHIND MENTEELOG</h2><p>Driven by Innovation: The Team Building Menteelog</p><div class="team-grid">${[['Jeff Gentapanan','Lead / Project Manager'],['Kyle Renzo Alis','Software Generalist'],['Sean Nicole Guipo','UI/UX Designer'],['John Paul Wendam','Frontend Developer'],['Jhodie Alyssa Ladran','Backend Developer'],['Christina Bernadett Porras','Backend Developer'],['Rolly Abella','Researcher']].map(([n,r])=>`<article>${photo('portrait','','Team portrait from supplied design')}<div><h3>${n}</h3><em>${r}</em><p>⌖ Philippines</p><button class="btn" data-action="team-connect" data-id="${n}">Connect</button></div></article>`).join('')}</div></section>`;}
export function authScreen(mode,role,{brand,icon,field}){const activate=mode==='activate',reset=mode==='reset';return `<div class="auth-reference"><section class="auth-reference-photo">${photo('group','auth-photo')}<div class="auth-tint"></div><img class="auth-watermark" src="./assets/logo.svg" alt=""><h1>Join the MenteeLog<br>Journey.<br>Step Forward into<br>Your Future.</h1><span class="auth-rule"></span><p>${icon('shield')} Official Student Mentorship Network</p></section><main class="auth-reference-main" id="main"><section class="auth-reference-card"><header>${brand()}<h2>${activate?'Activate Your MenteeLog Account':reset?'Reset Your MenteeLog Password':'MenteeLog – Authentication Hub'}</h2><p>${activate?'Complete the steps below to set up your account':reset?'Verify your token and set a new password':'Select your role to continue'}</p></header><div class="auth-reference-body">${activate?`<p class="auth-role-label">I AM A...</p><div class="activation-roles">${['Student','Supervisor'].map(r=>`<button type="button" class="btn ${role===r?'':'secondary'}" data-action="auth-role" data-id="${r}">${icon(r==='Student'?'users':'building')} ${r}</button>`).join('')}</div><form id="activation-form">${field(role==='Supervisor'?'CORPORATE EMAIL':'SR CODE','identifier',role==='Supervisor'?'email':'text','','required')}${field('REGISTERED EMAIL ADDRESS','email','email','','required')}<p class="form-error" role="alert"></p><button type="submit" class="btn full">Send Activation Link</button></form><a class="auth-return" href="#/login">← Back to Login</a>`:reset?`<form id="reset-form">${field('VERIFICATION TOKEN','token','text','','required minlength="6"')}${field('NEW PASSWORD','password','password','','required minlength="12"')}${field('CONFIRM PASSWORD','confirm','password','','required minlength="12"')}<p class="form-error" role="alert"></p><button type="submit" class="btn full">Reset Password</button></form><a class="auth-return" href="#/login">← Back to Login</a>`:`<div class="auth-tabs" role="group" aria-label="Authentication portals">${['Student','Supervisor','Coordinator'].map(r=>`<button class="${r===role?'selected':''}" data-action="auth-role" data-id="${r}" aria-pressed="${r===role}">${icon(r==='Student'?'users':r==='Supervisor'?'building':'users')} ${r}</button>`).join('')}</div><form id="login-form">${field(role==='Student'?'SR CODE':role==='Supervisor'?'CORPORATE EMAIL':'FACULTY ID','identifier',role==='Supervisor'?'email':'text','','required autocomplete="username"')}<div class="field"><label for="password">PASSWORD</label><div class="password-field"><input id="password" name="password" type="password" required autocomplete="current-password"><button type="button" data-action="toggle-password" aria-label="Show password">${icon('eye')}</button></div></div><button type="button" class="forgot-link" data-action="forgot">Forgot Password?</button><p class="form-error" role="alert"></p><button class="btn full" type="submit">Login as ${role}</button></form><p class="activate-link">First time here? <a href="#/activate">Activate ${role} Account</a></p><a class="auth-return" href="#/">← Back to Landing Page</a>`}</div></section></main></div>`;}
